CREATE TABLE mistri.integration_call (
    app text NOT NULL,
    key text NOT NULL,
    tenant text NOT NULL,
    integration text NOT NULL,
    action text NOT NULL,
    command text NOT NULL,
    state text NOT NULL,
    result_json text,
