CREATE TABLE mistri.integration_message (
    app text NOT NULL,
    key text NOT NULL,
    tenant text NOT NULL,
    channel text NOT NULL,
    recipient text NOT NULL,
    text text NOT NULL,
    state text NOT NULL,
    reason text,
    provider_id text,
    due_at bigint,
    consent integer,
    timezone text,
    attempts integer NOT NULL,
    at bigint NOT NULL,
    actor_kind text,
    CONSTRAINT integration_message_actor_kind_check CHECK ((actor_kind = ANY (ARRAY['account'::text, 'service'::text, 'public'::text, 'proven'::text]))),
    CONSTRAINT integration_message_consent_check CHECK ((consent = ANY (ARRAY[0, 1]))),
    CONSTRAINT integration_message_state_check CHECK ((state = ANY (ARRAY['sent'::text, 'held'::text, 'suppressed'::text, 'failed'::text])))
);
CREATE TABLE mistri.integration_meta (
